module scalarmult_wrapper (
  input               io_start,
  output              io_done,
  input               io_ready,
  input      [3:0]    io_mode,
  input      [7:0]    io_offsetRd,
  input      [7:0]    io_offsetWr,
  output     [8:0]    io_rdAddr,
  output     [8:0]    io_wrAddr,
  input      [511:0]  io_rdData,
  output              io_readEnable,
  output              io_writeEnable,
  output     [511:0]  io_wrData,
  input               clk,
  input               rst
);

  wire       [255:0]  scalarMult_io_memP_X;
  wire       [255:0]  scalarMult_io_memP_Y;
  wire                scalarMult_io_done;
  wire                scalarMult_io_wrCheck;
  wire       [7:0]    scalarMult_io_rdAddrPXY;
  wire       [7:0]    scalarMult_io_wrAddrPXY;
  wire                scalarMult_io_readEnable;
  wire                scalarMult_io_writeEnable;
  wire       [255:0]  scalarMult_io_wrMem_X;
  wire       [255:0]  scalarMult_io_wrMem_Y;
  wire       [8:0]    _zz_io_rdAddr;
  wire       [7:0]    _zz_io_rdAddr_1;
  wire       [8:0]    _zz_io_wrAddr;
  wire       [8:0]    _zz_io_wrAddr_1;
  wire       [7:0]    _zz_io_wrAddr_2;

  assign _zz_io_rdAddr_1 = (scalarMult_io_rdAddrPXY + io_offsetRd);
  assign _zz_io_rdAddr = {1'd0, _zz_io_rdAddr_1};
  assign _zz_io_wrAddr = {1'd0, scalarMult_io_wrAddrPXY};
  assign _zz_io_wrAddr_2 = (scalarMult_io_wrAddrPXY + io_offsetRd);
  assign _zz_io_wrAddr_1 = {1'd0, _zz_io_wrAddr_2};
  scalar_mult scalarMult (
    .io_start       (io_start                    ), //i
    .io_done        (scalarMult_io_done          ), //o
    .io_ready       (io_ready                    ), //i
    .io_wrCheck     (scalarMult_io_wrCheck       ), //o
    .io_mode        (io_mode[3:0]                ), //i
    .io_size_A1     (4'b1111                     ), //i
    .io_size_A2     (4'b1111                     ), //i
    .io_offsetWr    (io_offsetWr[7:0]            ), //i
    .io_rdAddrPXY   (scalarMult_io_rdAddrPXY[7:0]), //o
    .io_wrAddrPXY   (scalarMult_io_wrAddrPXY[7:0]), //o
    .io_memP_X      (scalarMult_io_memP_X[255:0] ), //i
    .io_memP_Y      (scalarMult_io_memP_Y[255:0] ), //i
    .io_readEnable  (scalarMult_io_readEnable    ), //o
    .io_writeEnable (scalarMult_io_writeEnable   ), //o
    .io_wrMem_X     (scalarMult_io_wrMem_X[255:0]), //o
    .io_wrMem_Y     (scalarMult_io_wrMem_Y[255:0]), //o
    .clk            (clk                         ), //i
    .rst            (rst                         )  //i
  );
  assign scalarMult_io_memP_X = io_rdData[511 : 256];
  assign scalarMult_io_memP_Y = io_rdData[255 : 0];
  assign io_rdAddr = _zz_io_rdAddr;
  assign io_wrAddr = (scalarMult_io_wrCheck ? _zz_io_wrAddr : _zz_io_wrAddr_1);
  assign io_readEnable = scalarMult_io_readEnable;
  assign io_writeEnable = scalarMult_io_writeEnable;
  assign io_wrData = {scalarMult_io_wrMem_X,scalarMult_io_wrMem_Y};
  assign io_done = scalarMult_io_done;

endmodule

